SELECT 
FROM follow_up


        AND patient_id = #{patientId}


        AND doctor_id = #{doctorId}


        AND (patient_name LIKE CONCAT('%', #{keyword}, '%')
             OR doctor_name LIKE CONCAT('%', #{keyword}, '%')
             OR project LIKE CONCAT('%', #{keyword}, '%'))


        AND status = #{status}


        AND type = #{type}


        AND date >= #{startDate}


        AND date <= #{endDate}


ORDER BY date DESC, create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM follow_up


        AND patient_id = #{patientId}


        AND doctor_id = #{doctorId}


        AND (patient_name LIKE CONCAT('%', #{keyword}, '%')
             OR doctor_name LIKE CONCAT('%', #{keyword}, '%')
             OR project LIKE CONCAT('%', #{keyword}, '%'))


        AND status = #{status}


        AND type = #{type}


        AND date >= #{startDate}


        AND date <= #{endDate}

SELECT 
FROM follow_up
WHERE doctor_id = #{doctorId}

    AND (patient_name LIKE CONCAT('%', #{request.keyword}, '%')
         OR project LIKE CONCAT('%', #{request.keyword}, '%'))


    AND status = #{request.status}


    AND type = #{request.type}


    AND date >= #{request.startDate}


    AND date <= #{request.endDate}

ORDER BY date DESC, create_time DESC
LIMIT #{request.pageSize} OFFSET #{request.offset}

